// MCP Client with Connection Pooling (TypeScript)
import { MCPClient, ConnectionPool } from '@mcp/sdk';
import { circuitBreaker } from 'resilience4j';

const pool = new ConnectionPool({
  minIdle: 20,
  maxConnections: 200,
  healthCheckInterval: 30000,
  timeout: 30000
});

const client = new MCPClient({
  serverUrl: 'https://mcp.enterprise.com',
  pool: pool,
  retryPolicy: {
    maxAttempts: 3,
    backoffMultiplier: 2,
    initialDelay: 1000,
    errorCodes: [429, 503, 504]
  }
});

// Circuit breaker wraps client calls
const breaker = circuitBreaker(client.invokeTool, {
  failureThreshold: 5,
  timeout: 30000,
  resetTimeout: 60000
});

try {
  const result = await breaker('analyze_credit_risk', {
    customer_id: '12345',
    idempotency_key: uuid()
  });
} catch (error) {
  logger.error('MCP invocation failed', {
    correlationId: ctx.correlationId,
    errorCode: error.code,
    errorType: error.type
  });
}

# MCP Server OAuth2 Scope Validation (Python)
from functools import wraps
from mcp_sdk import oauth2_introspect, AuditLogger

logger = AuditLogger(stream_to='splunk')

def require_scopes(*required_scopes):
    def decorator(func):
        @wraps(func)
        async def wrapper(request, *args, **kwargs):
            token = request.headers.get('Authorization').split(' ')[1]

            # Introspect token with auth server
            introspection = await oauth2_introspect(token)

            if not introspection['active']:
                logger.security_event('token_expired', {
                    'ip': request.client_ip,
                    'timestamp': datetime.utcnow().isoformat()
                })
                raise HTTPException(401, "Token expired")

            granted_scopes = set(introspection['scope'].split(' '))
            required = set(required_scopes)

            if not required.issubset(granted_scopes):
                logger.security_event('insufficient_scope', {
                    'required': list(required),
                    'granted': list(granted_scopes),
                    'agent_id': introspection['client_id']
                })
                raise HTTPException(403, "Insufficient scope")

            # Execute with audit logging
            logger.audit({
                'operation': func.__name__,
                'agent': introspection['client_id'],
                'scopes': list(granted_scopes),
                'correlation_id': request.correlation_id
            })

            return await func(request, *args, **kwargs)
        return wrapper
    return decorator

